import json,csv,collections,re,subprocess,os
DEV=os.environ.get('NWSAOM_DEV') or os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)),'..','..'))  # the nwsaom checkout that is inspected
import os
HERE=os.path.dirname(os.path.abspath(__file__))
rows=json.load(open(os.path.join(HERE,'rows.json')))
SECORDER=[]
for r in rows:
    if r['section'] not in SECORDER: SECORDER.append(r['section'])
commit=subprocess.run(['git','-C',DEV,'log','--oneline'],capture_output=True,text=True).stdout.splitlines()[0]
dirty=subprocess.run(['git','-C',DEV,'status','--short'],capture_output=True,text=True).stdout.strip()
base=lambda s:s.split(' (')[0]
cols=['section','shortName','effectName','varType','context','rsiena_roles','parameter','status','nwsaom_option','nwsaom_roles','validated','notes']
# csv
with open(os.path.join(HERE,'..','SAOM_EFFECTS_INVENTORY.csv'),'w',newline='') as f:
    w=csv.writer(f); w.writerow(['section','RSiena_shortName','RSiena_effectName','variable_type','interaction_context','RSiena_roles','internal_parameter_default','nwsaom_status','nwsaom_option','nwsaom_roles','validated_against_RSiena','notes'])
    for r in rows: w.writerow([r[c] for c in cols])
# counts
vts=['one-mode network','non-directed network','two-mode network','behavior','behavior (non-directed network)','rate (one-mode network)','rate (non-directed network)','rate (two-mode network)','rate (behavior)','rate (behavior (non-directed network))','rate (continuous behavior)','continuous behavior','gmm (one-mode network)','gmm (non-directed network)','gmm (two-mode network)','gmm (behavior)']
sts=['IMPLEMENTED','PARTIAL','NOT IMPLEMENTED','NOT PLANNED','UNKNOWN']
cnt=collections.Counter((r['varType'],base(r['status'])) for r in rows)
tot=collections.Counter(base(r['status']) for r in rows)
def esc(t): return str(t).replace('|','/').replace('\n',' ')
L=[]
a=L.append
a('# SAOM effects inventory: RSiena 1.6.6 versus `nwsaom`\n')
a('- **Date:** 2026-10-22')
a('- **nwsaom commit inspected:** `%s` (checkout `%s`)'%(commit,DEV))
a('- **Working tree state when the table was generated:** %s'%('clean (no uncommitted changes)' if not dirty else 'uncommitted changes present: '+esc(dirty.replace('\n','; '))))
a('- **How the RSiena list was generated:** `Rscript` with RSiena 1.6.6 installed: `getEffects()` on `sienaDataCreate()` objects for 12 data configurations built from `s501-s503`, `s50a`, `s50s` and made-up bipartite/non-directed/continuous data (first generated by an agent 2026-10-22; the row data are `docs/inventory_tools/rows.json`): (1) one-mode network with `coCovar`, `varCovar`, `coDyadCovar`, `varDyadCovar`; (2) network + behavior with the same covariates; (3) network + two behaviors; (4) two networks + behavior; (5) three networks; (6) bipartite with node-set covariates and a dyadic covariate; (7) bipartite + behavior; (8) one-mode + bipartite on shared node sets; (9) network + continuous (SDE) behavior; (10-12) the same for symmetrised (non-directed) networks. Plus `allEffects` (1.6.6) to catch the 17 shortNames those configurations cannot instantiate (settings effects, `sameXV*`, `toU`, `BFDeg`). Result: all 456 distinct shortNames of `allEffects` appear. Rows are unique per (variable type, shortName, interaction context), with `effectName` templated (`<dep>` = dependent variable name, `<v1>`/`<v2>` = interaction variables); role sets come from the `type` column of `getEffects()` (eval / endow / creation / rate / gmm). RSiena sections follow the manual (RSiena_Manual.tex, "Mathematical definition of effects": structural, dyadic covariate, monadic covariate, multiple network, behavioral, rate), sub-divided where the manual lists one long block.')
a('- **How nwsaom status was determined:** by reading `nwsaom.ado` (syntax line, guard lists for two-mode / symmetric / tvcov, `addterm()` blocks), `unw_saom.do` (`_SaomRSLabel1`, covariate-split helpers, behavior models), `nwsaom.sthlp`, `nwsaom_remarks.sthlp`, `native/saom_sim.c`, and `docs/nwsaom_DECISIONS.md` (decisions 1-54), `docs/nwsaom_WORKING.md`, `docs/SAOM_ROADMAP.md`. Validation flags come from those documents ("statistics identical to siena07 targets"). Stata was not run; nothing was built.')
a('- **Caveat:** RSiena 1.6.6 (installed) differs slightly from the source clone (1.6.13): the clone adds `WXZX` (not in 1.6.6). `inPop` reports internal parameter 0 in 1.6.6 `getEffects()`, `outPop`, `inAct`, `outActSqrt` report 1.')
a('- **The develop tree is being edited by another session** (protocol 33 was committed while this inventory was being written); statuses reflect the commit above. Maintained with `docs/inventory_tools/update_inventory.py` (append the new effects to UPDATES, run it): it regenerates this file and the CSV.\n')
a('Status legend: **IMPLEMENTED** (an nwsaom option gives the effect; `IMPLEMENTED (as X)` when the nwsaom option name differs from the RSiena shortName or covers it with a different parameter), **PARTIAL** (only a restricted form or a separate restricted command), **NOT IMPLEMENTED** (no option; or implemented elsewhere but refused for this variable type), **NOT PLANNED** (explicitly out of scope: continuous behavior), **UNKNOWN** (could not be determined from the code alone, reason in notes). Roles are RSiena effect types: `eval` = evaluation function, `endow` = endowment, `creation` = creation. "Validated" = documented statistic targets identical to siena07 (`yes`), `no` = no comparison recorded, `unknown`.\n')
a('## 1. Summary\n')
a('Total rows: **%d** (unique RSiena shortName x variable type x interaction context); distinct RSiena shortNames: **%d**.\n'%(len(rows),len(set(r['shortName'] for r in rows))))
a('| Variable type | '+' | '.join(sts)+' | Total |')
a('|---|'+'---:|'*(len(sts)+1))
for v in vts:
    t=sum(cnt[(v,s)] for s in sts)
    if t==0: continue
    a('| %s | '%v+' | '.join(str(cnt[(v,s)]) for s in sts)+' | %d |'%t)
a('| **Total** | '+' | '.join('**%d**'%tot[s] for s in sts)+' | **%d** |'%len(rows))
a('')
# per-section counts
a('Rows per manual section:\n')
a('| Section | Rows | IMPLEMENTED | PARTIAL | NOT IMPLEMENTED | NOT PLANNED | UNKNOWN |')
a('|---|---:|---:|---:|---:|---:|---:|')
for s in SECORDER:
    rs=[r for r in rows if r['section']==s]; c=collections.Counter(base(r['status']) for r in rs)
    a('| %s | %d | %d | %d | %d | %d | %d |'%(s,len(rs),c['IMPLEMENTED'],c['PARTIAL'],c['NOT IMPLEMENTED'],c['NOT PLANNED'],c['UNKNOWN']))
a('')
a('## 2. The 15 most commonly used RSiena effects that nwsaom still lacks (in order of importance)\n')
a('Ranked by how often they appear in applied SAOM papers (RSiena manual tutorials: selection and influence analyses of friendship and behavior, multiplex and dyadic-covariate models) and by the number of models they block. Effects counted as available: everything IMPLEMENTED or PARTIAL above.\n')
top=[
('1','`egoX`, `altX`, `egoPlusAltX` of the dependent behavior (network selection on the co-evolving behavior: "alcohol ego", "alcohol alter")','**DONE 2026-10-22** (`behegox`, `behaltx`, `behegoplusalt`, DECISIONS 56). Still open in the family: absDiffX, diffX, higher, egoSqX, altSqX ... with the dependent behavior.'),
('2','`effFrom` (covariate main effect on a behavior: gender, age, ... on drinking/smoking)','No covariate effects on behavior at all; the behavior side has only `linear quadratic avalt avsim`. Needed in most influence models.'),
('3','`indeg`, `outdeg` (effect of in-/outdegree on the behavior; also `recipDeg`, `isolate`)','Network-position effects on behavior are missing.'),
('4','`totAlt`, `totSim`, `avAltW`/`totAltW`, `avSimPopAlt`, `maxAlt`/`minAlt` (alternative influence mechanisms)','Only `avAlt` and `avSim` exist; total-alter and similarity-total variants are standard robustness checks.'),
('5','`avXAlt`, `avSameXAlt`, `totXAlt` (influence moderated by a covariate, e.g. same-gender influence)','Covariate-moderated influence has no counterpart.'),
('6','Cross-network effects `from`, `to`, `crprodRecip`, `crprodMutual`, `closure`, `sharedIn`, `cl.XWX` (multiplex / several dependent networks)','Only `crprod` exists, in the separate restricted subcommand `nwsaom multiplex` (outdegree + reciprocity + crprod, two waves, no covariates, no behavior).'),
('7','`transTriads`, `degPlus` (triadic closure and degree effects for non-directed networks)','The non-directed model offers only outdegree, transTies, balance, gwesp, cycle4, inPopSqrt, outAct, outInAss, isolate effects and covariate effects; `transTrip` is refused under `symmetric` and RSiena offers `transTriads` instead.'),
('8','Changing dyadic covariate `varDyadCovar` (`X`, `XRecip`) and changing-covariate versions of the other covariate effects (`absDiffX`, `egoXaltX`, `diffX`, `higher`, `egoSqX`, ...), `RateX` with a changing covariate, endow/creation with `tvcov()`','`tvcov()` supports only egox/altx/nodecov/samex/simx; `dyadcov()` takes one time-constant matrix.'),
('9','Covariate x triadic/popularity effects: `sameXTransTrip`, `simXTransTrip`, `homXTransTrip`, `sameXInPop`, `sameXOutAct`, `homXOutAct`, `inPopX`, `outActX`, `altXOutAct`','Homophily-moderated closure/popularity effects are not available (none of the covariate-interaction effects of the triad/degree families).'),
('10','Network rate effects `outRate`, `inRate`, `recipRate` (+ `Inv`, `Log` versions) and behavior `RateX`','Only a constant rate (jointly estimated) and `ratecov()` with constant node covariates exist.'),
('11','`denseTriads`','Deliberately deferred (DECISIONS 53: marking-based statistic with five configuration tables, parameter 5/6); a frequent triad-structure alternative to transTrip.'),
('12','Two-mode: `inPop`, `outActSqrt`, `gwespFBMix`, `sameXCycle4`, `sameXInPop`, `JoutMix`, two-mode + behavior (`bip` x `beh`), covariates other than egoX/altX','Two-mode supports 8 structural effects and egoX/altX only; behavior with a bipartite network is refused; `inpop`/`outactsqrt`/`isolatepop` pass the two-mode guard but are undocumented (UNKNOWN).'),
('13','Behavior interactions (`includeInteraction` for behavior effects, `behUnspInt`) and cross-behavior effects (`effFrom` between behaviors, `avGroupEgoX`)','`interact()` is for network effects only; several behaviors interact only through the network (DECISIONS 28).'),
('14','Covariate threshold/contrast effects: `egoPlusAltSqX`, `diffSqX`, `egoDiffX`, `altHigherEgoX`, `unequalX`, `egoLThresholdX`, `egoRThresholdX`, `altLThresholdX`, `altRThresholdX`, `degAbsDiffX`','Only 13 of the ~60 monadic covariate effects are available.'),
('15','Centred / ego-form degree variants and compression/primary-setting family: `inPop.c`, `outPop.c`, `outAct.c`, `inAct.c`, `outPopMore`, `outPopSqrtMore`, `avDeg`, `Jin`, `Jout`, `primary`, `nonPCompress`, `primCompress`','Lower priority: centred variants and niche effects; the primary-setting/compression family is architecturally blocked (ROADMAP unit 174).')]
a('| Rank | RSiena effect(s) | Why it matters / what nwsaom has instead |')
a('|---:|---|---|')
for t in top: a('| %s | %s | %s |'%t)
a('')
a('Other gaps not ranked: GMoM statistics (`*_gmm`; nwsaom estimates by Method of Moments only), settings effects (`settingSizeAct` ...; no settings concept), continuous (SDE) dependent variables (NOT PLANNED), Siena Bayes / maximum likelihood (not planned, DECISIONS 49; an siena08-style meta-analysis is planned).\n')
# verification
syn=''.join(open(DEV+'/nwsaom.ado').readlines()[190:215]).lower()
ado=open(DEV+'/nwsaom.ado').read(); mata=open(DEV+'/unw_saom.do').read(); hlp=open(DEV+'/nwsaom.sthlp').read(); c=open(DEV+'/native/saom_sim.c').read()
names='outdegree reciprocity transtrip transmedtrip transrectrip cycle3 cycle4 sqrtcycle4 transties balance gwesp gwespfb gwespbf gwespbb gwesprr between gwdspff gwdspfb nbrdist2 dblnbrdist2 inpop indegpopularity outpop outpopularity inact inactivity outactivity outactsqrt recipop recipopsqrt reciact reciactsqrt outtrunc outmore outthreshold outinv outsqinv outiso isolatenet antiiso antiiniso antiiniso2 inplus3 isolatepop outoutass ininass outinass inoutass nodeocov egox nodeicov altx nodecov nodematch samex simcov simx absdiffx egoxaltx diffx higher egosqx altsqx samexrecip simrecipx dyadcov dyadcovrecip ratecov tvcov behsim linear quadratic avalt avsim interact'.split()
a('## 3. Verification of IMPLEMENTED claims by grep in the develop tree\n')
a('For each nwsaom option named below (%d options, all claims of IMPLEMENTED/PARTIAL rows), the number of hits in the dev tree: `syntax` = occurrences in the `syntax [...]` option list of `nwsaom.ado` (lines 191-215), `ado+mata` = occurrences of the quoted term / `stat_saom_X` / `change_saom_X` / `addterm` references in `nwsaom.ado` and `unw_saom.do`, `help` = `{opt X}` entries in `nwsaom.sthlp`, `C` = case-insensitive occurrences in `native/saom_sim.c` (native termcode). A zero in one column is explained where relevant (`sqrtcycle4` registers the term `cycle4sqrt` with `stat_saom_cycle4sqrt`; `dblnbrdist2` registers term `nbrdist2twice`; `ratecov`/`tvcov` are handled by dedicated code paths without `addterm`; `egox`/`altx`/`samex`/`simx` are aliases of nodeocov/nodeicov/nodematch/simcov; `indegpopularity`/`outpopularity`/`inplus3` use shorter C names).\n'%len(names))
a('| nwsaom option | syntax | ado+mata | help | C |')
a('|---|---:|---:|---:|---:|')
for n in names:
    s_=len(re.findall(r'\b'+n+r'\b',syn)); b=len(re.findall(r'[\"\'(]'+n+r'[\"\')_]|stat_saom_'+n+r'\b|change_saom_'+n+r'\b|\"'+n+r'\"',ado+mata)); h=len(re.findall(r'\{opt[h]? '+n+r'\b',hlp)); cc=len(re.findall(n.upper(),c.upper()))
    a('| `%s` | %d | %d | %d | %d |'%(n,s_,b,h,cc))
a('')
a('Additional manual checks: the two-mode refusal list (nwsaom.ado lines ~544-551) and the symmetric refusal list (~1087-1091) were read to assign the two-mode and non-directed statuses; `_SaomRSLabel1` in `unw_saom.do` was read for the RSiena effect names nwsaom reports in `e(rsiena_labels)`.\n')
a('## 4. Other unresolved points\n')
a('- Two-mode: `inpop`, `outactsqrt` and `isolatepop` are not in the two-mode refusal list nor documented as available; they were not tested (Stata not run) and are marked UNKNOWN.')
a('- Non-directed networks: only the `outdegree` estimates were compared with siena07 (BJOINT); the other non-directed rows say `unknown` for validation although the effects are shared code with the directed model.')
a('- `outPopSqrt` / `inActSqrt` deliberately follow the documented sqrt statistic (= RSiena with parameter 1), not the RSiena 1.6.6 default (parameter 0), see RSiena issue #151 in docs/SAOM_ROADMAP.md.')
a('- The RSiena `effectName` column shows one representative spelling with `<dep>`, `<v1>`, `<v2>` placeholders; some effects print slightly different names depending on the number of waves/variables.')
a('- Role columns for RSiena are what `getEffects()` lists; for some effects RSiena lists endow/creation rows even though they are rarely meaningful.\n')
a('## 5. Tables by manual section\n')
a('Columns: shortName | effectName (as printed) | variable type | covariate/network context | RSiena roles | internal parameter (default) | nwsaom status | nwsaom option | roles in nwsaom | validated | notes.\n')
for s in SECORDER:
    rs=[r for r in rows if r['section']==s]
    a('### %s\n'%s)
    a('| shortName | effectName | variable type | context | RSiena roles | parameter | nwsaom status | nwsaom option | nwsaom roles | validated | notes |')
    a('|---|---|---|---|---|---|---|---|---|---|---|')
    for r in rs:
        a('| `%s` | %s | %s | %s | %s | %s | **%s** | %s | %s | %s | %s |'%(esc(r['shortName']),esc(r['effectName']),esc(r['varType']),esc(r['context']),esc(r['rsiena_roles']),esc(r['parameter']),esc(r['status']),esc(r['nwsaom_option']),esc(r['nwsaom_roles']),esc(r['validated']),esc(r['notes'])))
    a('')
open(os.path.join(HERE,'..','SAOM_EFFECTS_INVENTORY.md'),'w').write('\n'.join(L))
print(len(rows),dict(tot)); print(commit,dirty)
